// [MEDIUM_PRIORITY] UX_POLISH: Error state handled
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.messagingimport timber.log.Timberimport android.content.Contextimport android.content.Intentimport com.roshan.persona.connectivity.model.MessagingAppimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.delayimport kotlinx.coroutines.withContext/** * NOUS — Outbound Executor (Module 11 v3 — Step 11.2, Elite Feature). * * Orchestrates outbound messages to WhatsApp/Telegram/Signal/SMS. * * ## The v3 "Full-Spectrum" flow (per strategy v3 §"Full-Spectrum Messaging Unification") * * ``` * User: "Message Mom on WhatsApp that I'm late" *   ↓ * OutboundExecutor.send(MessagingApp.WHATSAPP, "+919876543210", "I'm late") *   ↓ * 1. MessagingIntentBuilder.buildWhatsAppIntent(phone, message) *    → Intent(ACTION_VIEW, "https://wa.me/919876543210?text=I'm+late") *   ↓ * 2. context.startActivity(intent) → WhatsApp chat opens with pre-filled message *   ↓ * 3. delay(1500ms) → wait for chat screen to load *   ↓ * 4. MessagingAccessibilityBridge.clickSendButton(WHATSAPP) *    → AccessibilityService finds "Send" button → clicks it *   ↓ * 5. MessagingAccessibilityBridge.verifyMessageSent(WHATSAPP) *    → Checks input field is empty → confirms message sent *   ↓ * 6. Return SendResult.SUCCESS * ``` * * ## Fallback: Manual Mode * * If the accessibility service is not enabled (user hasn't granted permission), * the OutboundExecutor opens the chat with the pre-filled message but does * NOT click "Send" automatically. The user must tap "Send" manually. * * Result: `SendResult.MANUAL_CONFIRMATION_REQUIRED` * * ## Privacy * *  - The message text is passed via Intent (local, on-device). *  - No message content is logged or sent to any server. *  - The accessibility service only interacts with the messaging app's UI *    (finds + clicks the "Send" button) — it does NOT read message content. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Full-Spectrum Messaging Unification</a> */class OutboundExecutor(    private val context: Context,    private val accessibilityBridge: MessagingAccessibilityBridge,    private val dispatcher: CoroutineDispatcher,) {    /**     * Send a message via [app] to [phoneNumber].     *     * @param app the messaging app to use.     * @param phoneNumber the recipient's phone number.     * @param message the message text.     * @return the send result.     */    suspend fun send(        app: MessagingApp,        phoneNumber: String,        message: String,    ): SendResult = withContext(dispatcher) {        Timber.tag(TAG).i("Sending via ${app.displayLabel}: to=$phoneNumber, msgLen=${message.length}")        // 1. Build the intent.        val intent = MessagingIntentBuilder.buildIntent(app, phoneNumber, message)            ?: return@withContext SendResult.FAILED("Failed to build intent for ${app.displayLabel}")        // 2. Check if the app is installed.        if (!isAppInstalled(app)) {            Timber.tag(TAG).w("${app.displayLabel} is not installed.")            return@withContext SendResult.APP_NOT_INSTALLED(app)        }        // 3. Open the chat.        val launched = launchIntent(intent)        if (!launched) {            return@withContext SendResult.FAILED("Failed to launch ${app.displayLabel}")        }        // 4. Check accessibility service.        if (!accessibilityBridge.isServiceEnabled()) {            Timber.tag(TAG).i("Accessibility not enabled — manual confirmation required.")            return@withContext SendResult.MANUAL_CONFIRMATION_REQUIRED(app)        }        // 5. Wait for chat screen to load.        delay(CHAT_LOAD_DELAY_MS)        // 6. Click "Send" button.        val clicked = accessibilityBridge.clickSendButton(app)        if (!clicked) {            Timber.tag(TAG).w("Failed to click Send button in ${app.displayLabel}.")            return@withContext SendResult.FAILED("Could not find Send button in ${app.displayLabel}")        }        // 7. Verify message was sent.        delay(VERIFY_DELAY_MS)        val verified = accessibilityBridge.verifyMessageSent(app)        if (!verified) {            Timber.tag(TAG).w("Send verification failed for ${app.displayLabel}.")            return@withContext SendResult.SEND_BUTTON_CLICKED_BUT_UNVERIFIED(app)        }        Timber.tag(TAG).i("Message sent successfully via ${app.displayLabel}.")        SendResult.SUCCESS(app)    }    /**     * Send a message via SMS (no accessibility needed — uses SmsManager directly).     *     * This is a convenience method — SMS doesn't need the AccessibilityBridge     * because SmsManager.sendTextMessage() works programmatically.     *     * @param phoneNumber the recipient's phone number.     * @param message the message text.     * @return the send result.     */    suspend fun sendSms(phoneNumber: String, message: String): SendResult = withContext(dispatcher) {        Timber.tag(TAG).i("Sending SMS: to=$phoneNumber, msgLen=${message.length}")        try {            val smsManager = android.telephony.SmsManager.getDefault()            smsManager.sendTextMessage(phoneNumber, null, message, null, null)            Timber.tag(TAG).i("SMS sent successfully.")            SendResult.SUCCESS(MessagingApp.SMS)        } catch (e: SecurityException) {            Timber.tag(TAG).w("SMS permission denied", e)            SendResult.PERMISSION_DENIED("SEND_SMS")        } catch (t: Throwable) {            Timber.tag(TAG).e("SMS send failed", t)            SendResult.FAILED(t.message ?: "Unknown SMS error")        }    }    // ─── Helpers ───────────────────────────────────────────────────────────    /** Check if a messaging app is installed on the device. */    internal fun isAppInstalled(app: MessagingApp): Boolean {        val packageName = app.packageName ?: return true  // SMS is always "installed"        return try {            context.packageManager.getPackageInfo(packageName, 0)            true        } catch (t: Throwable) {            false        }    }    /** Launch an intent, return true if successful. */    internal fun launchIntent(intent: Intent): Boolean {        return try {            context.startActivity(intent)            true        } catch (t: Throwable) {            Timber.tag(TAG).w("Failed to launch intent", t)            false        }    }    private companion object {        private const val TAG = "OutboundExecutor"        private const val CHAT_LOAD_DELAY_MS = 1500L        private const val VERIFY_DELAY_MS = 500L    }}// ──────────────────────────────────────────────────────────────────────────/** * Result of an outbound message send attempt. */sealed interface SendResult {    /** Message sent successfully. */    data class SUCCESS(val app: MessagingApp) : SendResult    /** App is not installed on the device. */    data class APP_NOT_INSTALLED(val app: MessagingApp) : SendResult    /** Accessibility not enabled — user must tap "Send" manually. */    data class MANUAL_CONFIRMATION_REQUIRED(val app: MessagingApp) : SendResult    /** Send button was clicked but verification failed (message may or may not have sent). */    data class SEND_BUTTON_CLICKED_BUT_UNVERIFIED(val app: MessagingApp) : SendResult    /** Permission denied. */    data class PERMISSION_DENIED(val permission: String) : SendResult    /** Send failed. */    data class FAILED(val reason: String) : SendResult}